def test_on_modify_limit_update_emits_effective_boundaries():
    """Changing chain limits should acknowledge both boundaries without speculative dates."""
    hook = _find_hook_file("on-modify.nautical")
    mod = _load_hook_module(hook, "_nautical_on_modify_limit_update_panel_test")
    old = {
        "uuid": "00000000-0000-0000-0000-000000000450",
        "description": "limited nautical task",
        "status": "pending",
        "cp": "1d",
        "chain": "on",
        "chainID": "abcd1234",
        "link": 2,
        "chainMax": 5,
        "chainUntil": "20260810T070000Z",
    }
    new = {**old, "chainMax": 8, "chainUntil": "20260820T070000Z"}
    cleared = dict(new)
    cleared.pop("chainMax")
    cleared.pop("chainUntil")
    panels = []

    orig_panel = mod._panel
    orig_print_task = mod._print_task
    try:
        mod._panel = lambda title, rows, *, kind=None: panels.append((title, list(rows), kind))
        mod._print_task = lambda _task: None
        mod._handle_non_completion_modify(old, new)
        mod._handle_non_completion_modify(new, cleared)
    finally:
        mod._panel = orig_panel
        mod._print_task = orig_print_task

    expect(len(panels) == 2, f"each limit update should emit one panel: {panels!r}")
    title, rows, kind = panels[0]
    expect(title == "⚓ Nautical recurrence updated" and kind == "note", f"unexpected limit panel: {panels!r}")
    expect(
        ("Changed", "Max links: [dim]5[/] [cyan]→[/] [bold]8[/]") in rows,
        f"missing styled chainMax update: {rows!r}",
    )
    expect(
        any(
            label == "Changed" and "Chain end point:" in value and "2026-08-10" in value and "2026-08-20" in value
            for label, value in rows
        ),
        f"missing localized chainUntil update: {rows!r}",
    )
    expect(("Final link", "#8") in rows, f"missing final link boundary: {rows!r}")
    expect(
        sum(label == "Changed" and "Chain end point:" in str(value) for label, value in rows) == 1,
        f"chain end point should not be repeated: {rows!r}",
    )
    expect(("Effective", "Whichever boundary is reached first") in rows, f"missing effective limit rule: {rows!r}")
    expect(("Chain limits", "None") in panels[1][1], f"clearing both limits should be explicit: {panels[1]!r}")
    expect(("Removed", "Max links: [dim]8[/]") in panels[1][1], f"cleared max link should be marked removed: {panels[1]!r}")
    expect(any(label == "Removed" and "Chain end point:" in str(value) for label, value in panels[1][1]), f"cleared chain end should be marked removed: {panels[1]!r}")


def test_modify_lifecycle_routes_and_promotes_new_nautical_tasks():
    """Modify lifecycle helper should classify and promote newly Nautical tasks explicitly."""
    ml = core._import_sibling("modify_lifecycle")
    expect(
        not ml.task_has_nautical_fields({"chainid": "legacy-1234"}),
        "lowercase chainid should not count as Nautical state",
    )
    expect(
        not ml.task_has_nautical_fields({"anchor_mode": "skip"}),
        "anchor_mode alone should not count as Nautical state",
    )
    expect(
        ml.task_has_nautical_chain_fields({"chainID": "abcd1234"}),
        "canonical chainID should still count as chain bookkeeping",
    )
    expect(
        ml.task_has_nautical_fields({"chainID": "abcd1234"}),
        "canonical chainID should still count as Nautical state",
    )
    old = {"uuid": "00000000-0000-0000-0000-000000000447", "status": "pending"}
    new = {
        "uuid": "00000000-0000-0000-0000-000000000447",
        "status": "pending",
        "anchor_file": "2026.csv",
        "chain": "off",
    }
    route = ml.classify_modify_route(
        old,
        new,
        is_non_completion_modify=lambda old_task, new_task: (old_task.get("status") == new_task.get("status")) or (new_task.get("status") != "completed"),
    )
    expect(not route.is_deleted, f"new task should not be deleted, got {route}")
    expect(route.has_nautical_fields, f"new task should be nautical, got {route}")
    expect(route.is_non_completion, f"new task should be non-completion modify, got {route}")
    source = ml.promote_newly_nautical_task(old, new, short_uuid=lambda u: str(u).split("-")[0] if u else "")
    expect(source == "anchor_file", f"expected anchor_file promotion source, got {source!r}")
    expect(new.get("chain") == "on", f"promotion should set chain:on, got {new!r}")
    expect(bool((new.get("chainID") or "").strip()), f"promotion should stamp chainID, got {new!r}")

    disabled_old = {"uuid": "00000000-0000-0000-0000-000000000448", "status": "pending", "anchor": "w:mon", "chain": "on"}
    disabled_new = dict(disabled_old)
    disabled_new["chain"] = "off"
    trans = ml.apply_nautical_transition(disabled_old, disabled_new, short_uuid=lambda u: str(u).split("-")[0] if u else "")
    expect(trans.state == "disabled", f"expected disabled transition, got {trans!r}")
    expect("chain:off" in trans.reason, f"expected chain-off reason, got {trans!r}")
    expect(disabled_new.get("chain") == "off", f"disabled transition should keep chain off, got {disabled_new!r}")

    resumed_new = dict(disabled_new)
    resumed_new["chain"] = "on"
    trans = ml.apply_nautical_transition(disabled_new, resumed_new, short_uuid=lambda u: str(u).split("-")[0] if u else "")
    expect(trans.state == "resumed", f"expected resumed transition, got {trans!r}")
    expect(trans.source == "anchor", f"expected resumed anchor source, got {trans!r}")

    changes = ml.recurrence_setting_changes(
        {"anchor": "w:mon", "omit": "", "chain": "on"},
        {"anchor": "w:tue", "omit": "y:apr", "chain": "on"},
    )
    expect(changes == [("anchor", "w:mon", "w:tue"), ("omit", "", "y:apr")], f"unexpected recurrence setting changes: {changes!r}")


def test_chainid_legacy_reads_do_not_drive_chain_identity():
    """Lowercase chainid should no longer participate in chain identity helpers."""
    import uuid
    import nautical_core.exit_queries as exit_queries
    import nautical_core.modify_chain_reads as modify_chain_reads
    import nautical_core.modify_spawn_prep as modify_spawn_prep

    parent = {"chainid": "legacy-1", "uuid": "parent-uuid"}
    child = {"chainid": "legacy-1", "link": 2}
    with_legacy = modify_spawn_prep.stable_child_uuid(
        parent,
        child,
        task_uuid_or_empty=lambda task: str(task.get("uuid") or "").strip(),
        coerce_int=core.coerce_int,
        stable_child_uuid_namespace=uuid.NAMESPACE_URL,
    )
    without_legacy = modify_spawn_prep.stable_child_uuid(
        {"uuid": "parent-uuid"},
        {"link": 2},
        task_uuid_or_empty=lambda task: str(task.get("uuid") or "").strip(),
        coerce_int=core.coerce_int,
        stable_child_uuid_namespace=uuid.NAMESPACE_URL,
    )
    expect(with_legacy == without_legacy, "legacy chainid should not change stable child UUIDs")
    expect(
        modify_chain_reads.existing_next_lookup({"chainid": "legacy-1", "link": 2}, 3, export_uuid_short_cached=lambda _ref: None, get_chain_export=lambda *_args, **_kwargs: [] ).is_absent,
        "legacy chainid should not drive existing next task lookup",
    )
    expect(
        exit_queries.existing_equivalent_child({"chainid": "legacy-1", "link": 2}, task_cmd_prefix=["task"], run_task=lambda *_args, **_kwargs: (False, "", ""), timeout=0.1, retries=0, retry_delay=0.0, is_lock_error=lambda _err: False, short_uuid_fn=lambda value: value).err == "missing chain slot",
        "legacy chainid should not satisfy equivalent-child lookup",
    )


