def test_perf_budget_config_covers_cache_io_checks():
    """Perf budgets should cover cache I/O, seasonal scheduling, and normalized hook latency."""
    cfg_path = Path(DEV_TOOLS) / "perf_budget.json"
    obj = json.loads(cfg_path.read_text(encoding="utf-8"))
    budgets = obj.get("budgets_seconds") if isinstance(obj, dict) else None
    workload = obj.get("workload") if isinstance(obj, dict) else None
    expect(isinstance(budgets, dict), "budgets_seconds must be present")
    expect(isinstance(workload, dict), "workload must be present")
    expect("cache_save" in budgets, "cache_save budget missing")
    expect("cache_load_hot" in budgets, "cache_load_hot budget missing")
    expect("queue_schema_hot" in budgets, "queue_schema_hot budget missing")
    expect("queue_schema_cold" in budgets, "queue_schema_cold budget missing")
    expect("cache_save_rounds" in workload, "cache_save_rounds missing from workload")
    expect("cache_load_rounds" in workload, "cache_load_rounds missing from workload")
    expect("queue_schema_hot_rounds" in workload, "queue_schema_hot_rounds missing from workload")
    expect("queue_schema_cold_rounds" in workload, "queue_schema_cold_rounds missing from workload")
    expressions = set(workload.get("expressions") or [])
    expect("y:d60,d-1" in expressions, "year-day latency workload missing")
    expect("y:w20 + w:mon" in expressions, "ISO-week latency workload missing")
    seasonal = obj.get("seasonal_workload") if isinstance(obj, dict) else None
    expect(isinstance(seasonal, dict), "seasonal_workload must be present")
    seasonal_expressions = set(seasonal.get("expressions") or [])
    expect(
        "(w:mon)@in-spring=first,last@t=09:00,17:00" in seasonal_expressions,
        "multi-time seasonal latency workload missing",
    )
    expect(
        "(y:02-29)@in-winter=first" in seasonal_expressions,
        "sparse seasonal latency workload missing",
    )
    expect(
        {
            "seasonal_parse_validate",
            "seasonal_next_after",
            "seasonal_build_hints",
        }
        <= set(budgets),
        "seasonal performance budgets are incomplete",
    )
    hook_fast_path = obj.get("hook_fast_path") if isinstance(obj, dict) else None
    expect(isinstance(hook_fast_path, dict), "hook_fast_path config must be present")
    expect(int(hook_fast_path.get("repeats") or 0) >= 3, "hook fast-path benchmark needs repeated samples")
    expect(
        float(hook_fast_path.get("managed_layout_max_ratio") or 0.0) >= 1.0,
        "managed hook layout ratio budget must allow ordinary timing jitter",
    )
    ratios = hook_fast_path.get("max_ratio") if isinstance(hook_fast_path.get("max_ratio"), dict) else {}
    expect(
        {"hook_plain_add", "hook_plain_modify", "hook_nautical_ordinary_modify", "hook_empty_exit"} <= set(ratios),
        f"hook ratio budgets are incomplete: {ratios}",
    )
    workflow_perf = obj.get("workflow_perf") if isinstance(obj, dict) else None
    expect(isinstance(workflow_perf, dict), "workflow_perf config must be present")
    workflow_budgets = workflow_perf.get("budgets_seconds") if isinstance(workflow_perf, dict) else None
    expect(isinstance(workflow_budgets, dict), "workflow_perf budgets_seconds must be present")
    expect(
        {
            "workflow_cp_completion",
            "workflow_cp_completion_nonfinal",
            "workflow_cp_completion_nonfinal_idempotent",
            "workflow_anchor_completion",
            "workflow_anchor_completion_nonfinal",
            "workflow_anchor_completion_nonfinal_idempotent",
            "workflow_queue_drain",
            "workflow_reconcile",
        }
        <= set(workflow_budgets or {}),
        f"expensive workflow budgets are incomplete: {workflow_budgets}",
    )


def test_perf_hook_fast_path_ratio_enforcement():
    """Hook latency checks should enforce the normalized fast/full median ratio."""
    perf = _load_hook_module(
        os.path.join(DEV_TOOLS, "nautical_perf_budget.py"),
        "_nautical_hook_perf_ratio_test",
    )

    def clearly_faster(_hook_path, *, input_text, env, expected_task):
        _ = (input_text, expected_task)
        return 0.100 if env.get("NAUTICAL_BENCH_FORCE_FULL") == "1" else 0.050

    perf._run_hook_timed = clearly_faster
    passing = perf._measure_hook_fast_path(
        "hook_test",
        Path("unused-hook"),
        input_text="{}",
        expected_task={},
        base_env={},
        repeats=3,
        max_ratio=0.8,
    )
    expect(passing.get("pass") is True, f"clear fast-path improvement should pass: {passing}")
    expect(abs(float(passing.get("fast_to_full_ratio")) - 0.5) < 0.001, f"unexpected ratio: {passing}")

    def insufficient_gain(_hook_path, *, input_text, env, expected_task):
        _ = (input_text, expected_task)
        return 0.100 if env.get("NAUTICAL_BENCH_FORCE_FULL") == "1" else 0.090

    perf._run_hook_timed = insufficient_gain
    failing = perf._measure_hook_fast_path(
        "hook_test",
        Path("unused-hook"),
        input_text="{}",
        expected_task={},
        base_env={},
        repeats=3,
        max_ratio=0.8,
    )
    expect(failing.get("pass") is False, f"insufficient fast-path improvement should fail: {failing}")

    perf._run_hook_timed = lambda *_args, **_kwargs: 0.060
    managed = perf._measure_managed_hook_latency(
        "managed_hook_test",
        Path("unused-hook"),
        input_text="{}",
        expected_task={},
        base_env={"NAUTICAL_CORE_PATH": "/source", "NAUTICAL_TRUST_CORE_PATH": "1"},
        repeats=3,
        baseline_median_s=0.050,
        max_ratio=1.5,
    )
    expect(managed.get("pass") is True, f"reasonable managed-layout overhead should pass: {managed}")
    expect(
        abs(float(managed.get("managed_to_source_ratio")) - 1.2) < 0.001,
        f"unexpected managed/source ratio: {managed}",
    )


def test_hook_runtime_retains_module_import_failure_details():
    """Required module failures should identify the underlying import error."""
    from nautical_core.hook_runtime import HookModuleAccess

    access = HookModuleAccess(
        {},
        {"broken": ("_broken", "_broken_failed", "broken.py", "nautical_core.no_such_module_for_test")},
    )
    expect(access.module("broken", required=False) is None, "broken module unexpectedly loaded")
    expect("ModuleNotFoundError" in access.errors.get("broken", ""), f"missing import detail: {access.errors}")
    try:
        access.module("broken")
    except RuntimeError as exc:
        expect("ModuleNotFoundError" in str(exc), f"required module error hid import detail: {exc}")
    else:
        raise AssertionError("required broken module did not fail")


def test_queue_state_migration_returns_typed_failure_details():
    """State migration failures should be returned instead of silently discarded."""
    from nautical_core import queue_store

    with tempfile.TemporaryDirectory() as td:
        current = Path(td) / "new" / "queue.db"
        legacy = Path(td) / "queue.db"
        legacy.write_text("legacy", encoding="utf-8")
        original_replace = queue_store.os.replace
        try:
            queue_store.os.replace = lambda *_args, **_kwargs: (_ for _ in ()).throw(PermissionError("read-only"))
            issues = queue_store.migrate_legacy_state(
                tw_data_dir=Path(td),
                file_pairs=((current, legacy),),
            )
        finally:
            queue_store.os.replace = original_replace
        expect(len(issues) == 1, f"migration failure was not retained: {issues}")
        expect(issues[0].current == str(current), f"migration issue lost current path: {issues}")
        expect("PermissionError" in issues[0].error, f"migration issue lost exception type: {issues}")


def test_queue_state_migration_moves_database_sidecars_under_one_lock():
    """Legacy queue files should converge as one serialized migration unit."""
    from nautical_core import queue_store

    with tempfile.TemporaryDirectory() as td:
        root = Path(td)
        legacy = root / ".nautical_queue.db"
        legacy.write_text("db", encoding="utf-8")
        Path(str(legacy) + "-wal").write_text("wal", encoding="utf-8")
        Path(str(legacy) + "-shm").write_text("shm", encoding="utf-8")

        issues = queue_store.migrate_nautical_state(tw_data_dir=root)
        current = queue_store.queue_db_path(root)
        expect(not issues, f"unexpected migration issues: {issues}")
        expect(current.read_text(encoding="utf-8") == "db", "database was not migrated")
        expect(Path(str(current) + "-wal").read_text(encoding="utf-8") == "wal", "WAL was not migrated")
        expect(Path(str(current) + "-shm").read_text(encoding="utf-8") == "shm", "SHM was not migrated")
        try:
            with queue_store.state_migration_lock(root, timeout=0.1):
                pass
        except Exception as exc:
            raise AssertionError(f"migration lock was not released: {exc}") from exc


def test_queue_state_migration_rejects_cross_process_lock_contention():
    """A second process must defer rather than move a partially-owned state set."""
    from nautical_core import queue_store

    with tempfile.TemporaryDirectory() as td:
        root = Path(td)
        ready = root / "ready"
        script = (
            "import sys, time; "
            "from pathlib import Path; "
            "from nautical_core.queue_store import state_migration_lock; "
            "root=Path(sys.argv[1]); ready=Path(sys.argv[2]); "
            "lock=state_migration_lock(root, timeout=2); lock.__enter__(); "
            "ready.write_text('ready'); time.sleep(5); lock.__exit__(None, None, None)"
        )
        proc = subprocess.Popen([sys.executable, "-c", script, str(root), str(ready)], cwd=ROOT)
        try:
            deadline = time.time() + 2.0
            while not ready.exists() and time.time() < deadline:
                time.sleep(0.01)
            expect(ready.exists(), "migration lock holder did not start")
            issues = queue_store.migrate_nautical_state(tw_data_dir=root, lock_timeout=0.1)
            expect(len(issues) == 1, f"lock contention was not reported: {issues}")
            expect("TimeoutError" in issues[0].error, f"lock failure lost its cause: {issues}")
        finally:
            proc.terminate()
            proc.wait(timeout=3)


