def test_native_until_carry_descriptions():
    """Calendar and exact expiration policies should have concise, stable descriptions."""
    add_validation = core._import_sibling("add_validation")
    due = datetime(2026, 8, 3, 10, 0, tzinfo=timezone.utc)
    same_day = datetime(2026, 8, 3, 18, 0, tzinfo=timezone.utc)
    next_day = datetime(2026, 8, 4, 9, 0, tzinfo=timezone.utc)
    exact = datetime(2026, 8, 4, 0, 0, 1, tzinfo=timezone.utc)
    identity = lambda value: value

    expect(
        add_validation.describe_native_until_carry(same_day, due, to_local=identity) == "Same day at 18:00",
        "same-day calendar expiration description was wrong",
    )
    expect(
        add_validation.describe_native_until_carry(next_day, due, to_local=identity) == "1 calendar day later at 09:00",
        "next-day calendar expiration description was wrong",
    )
    expect(
        add_validation.describe_native_until_carry(exact, due, to_local=identity) == "Exact · 14h 00m 01s after occurrence",
        "exact expiration description was wrong",
    )


def test_on_add_preview_distinguishes_expiration_from_chain_end_point():
    """Add previews should distinguish native expiration from chain boundaries."""
    hook = _find_hook_file("on-add.nautical")
    base = {
        "status": "pending",
        "entry": "20260720T090000Z",
        "due": "20260803T100000Z",
        "until": "20260803T180000Z",
        "chainUntil": "20260831T210000Z",
        "chainMax": 3,
    }
    cases = (
        dict(base, uuid="00000000-0000-0000-0000-000000000141", description="CP expiry preview", cp="7d"),
        dict(
            base,
            uuid="00000000-0000-0000-0000-000000000142",
            description="Anchor expiry preview",
            anchor="w:mon",
            anchor_mode="skip",
        ),
    )
    for task in cases:
        proc = _run_hook_script(hook, task, env_extra={"NO_COLOR": "1"})
        expect(proc.returncode == 0, f"preview failed: {proc.stderr!r}")
        expect(_assert_stdout_json_only(proc.stdout).get("until") == task["until"], "native until changed")
        panel = _strip_markup(proc.stderr)
        for label in ("Expiration", "First expires", "Chain end point", "Last occurrence", "Future links"):
            expect(label in panel, f"{label!r} missing from preview: {panel!r}")
        expires_local = core.to_local(core.parse_dt_any(task["until"]))
        expected_policy = f"Same day at {expires_local.hour:02d}:{expires_local.minute:02d}"
        expect(expected_policy in panel, f"calendar expiration policy missing from preview: {panel!r}")
        expect("2026-08-17" in panel, f"chainMax should determine the effective last occurrence: {panel!r}")
        expect("Final (until)" not in panel, f"ambiguous legacy label remains: {panel!r}")


def test_on_add_preview_fails_closed_when_evaluator_initialization_fails():
    """A shared evaluator failure must never fall back to legacy scheduling callbacks."""
    hook = _find_hook_file("on-add.nautical")
    mod = _load_hook_module(hook, "_nautical_on_add_evaluator_failure_test")
    if hasattr(mod, "_load_core"):
        mod._load_core()

    now_utc = mod.core.build_local_datetime(date(2026, 4, 12), (12, 0)).astimezone(timezone.utc)
    task = {
        "uuid": "00000000-0000-0000-0000-000000000143",
        "description": "evaluator initialization failure",
        "status": "pending",
        "entry": mod.core.fmt_isoz(now_utc),
        "anchor": "w:mon",
        "anchor_mode": "skip",
        "chain": "on",
        "chainID": "00000000",
    }
    ctx = mod._build_on_add_context(task, now_utc, mod.core.to_local(now_utc))
    panels = []
    evaluator_cls = importlib.import_module("nautical_core.recurrence_evaluator").RecurrenceEvaluator
    original_from_task = evaluator_cls.__dict__["from_task"]
    original_next = mod._anchor_next_occurrence_after_local_dt

    def fail_from_task(cls, *args, **kwargs):
        raise RuntimeError("astronomy profile is unavailable")

    try:
        evaluator_cls.from_task = classmethod(fail_from_task)
        mod._anchor_next_occurrence_after_local_dt = lambda *_args, **_kwargs: (_ for _ in ()).throw(
            AssertionError("legacy scheduler fallback was called")
        )
        mod._panel = lambda title, rows, **kwargs: panels.append((title, list(rows), kwargs))
        mod._emit_task_json = lambda *_args, **_kwargs: (_ for _ in ()).throw(
            AssertionError("failed preview must not emit task JSON")
        )
        try:
            mod._handle_anchor_preview_on_add_context(ctx, prof=mod._NoopProfiler())
        except SystemExit as exc:
            expect(exc.code == 1, f"unexpected evaluator failure exit code: {exc.code!r}")
        else:
            raise AssertionError("evaluator initialization failure was accepted")
    finally:
        evaluator_cls.from_task = original_from_task
        mod._anchor_next_occurrence_after_local_dt = original_next

    expect(panels and panels[-1][0] == "❌ Invalid Chain", f"missing evaluator error panel: {panels!r}")
    rows = panels[-1][1]
    expect(any(label == "Recurrence evaluator" for label, _value in rows), f"missing evaluator error detail: {rows!r}")
    expect(any(label == "Fix" for label, _value in rows), f"missing evaluator remediation: {rows!r}")


