def test_reconcile_candidate_and_plan_paths():
    """Hookless-completion repair should target only active completed orphans."""
    import nautical_core.reconcile as reconcile

    parent = {
        "uuid": "11111111-0000-0000-0000-000000000001",
        "status": "completed",
        "description": "remote completion",
        "cp": "P1D",
        "chain": "on",
        "chainID": "11111111",
        "link": 2,
        "due": "20260101T090000Z",
        "end": "20260101T100000Z",
    }
    expect(reconcile.is_orphan_completion_candidate(parent), "completed active chain without nextLink should be a candidate")
    with_next = dict(parent, nextLink="22222222")
    expect(not reconcile.is_orphan_completion_candidate(with_next), "linked completion should not be a candidate")
    chain_off = dict(parent, chain="off")
    expect(not reconcile.is_orphan_completion_candidate(chain_off), "chain:off completion should not be a candidate")

    existing = [
        {
            "uuid": "22222222-0000-0000-0000-000000000002",
            "chainID": "11111111",
            "link": 3,
            "status": "pending",
            "prevLink": "11111111",
        }
    ]
    plan = reconcile.build_reconcile_plan(parent, existing_children=existing, hook=None)
    expect(plan.action == "backfill_nextlink" and plan.child_short == "22222222", f"unexpected backfill plan: {plan}")
    duplicate = {
        **existing[0],
        "uuid": "33333333-0000-0000-0000-000000000003",
    }
    ambiguous = reconcile.build_reconcile_plan(parent, existing_children=[*existing, duplicate], hook=None)
    expect(
        ambiguous.action == "error" and "multiple tasks" in ambiguous.reason,
        f"duplicate next slots must fail closed: {ambiguous}",
    )
    nonreciprocal = reconcile.build_reconcile_plan(
        parent,
        existing_children=[dict(existing[0], prevLink="deadbeef")],
        hook=None,
    )
    expect(
        nonreciprocal.action == "error" and "prevLink" in nonreciprocal.reason,
        f"nonreciprocal next slot must fail closed: {nonreciprocal}",
    )
    recurrence_mismatch = reconcile.build_reconcile_plan(
        parent,
        existing_children=[dict(existing[0], cp="P2D")],
        hook=None,
    )
    expect(
        recurrence_mismatch.action == "error" and "recurrence field cp" in recurrence_mismatch.reason,
        f"mismatched recurrence child must fail closed: {recurrence_mismatch}",
    )

    class FakeCore:
        @staticmethod
        def coerce_int(value, default=0):
            try:
                return int(value)
            except Exception:
                return default

    from nautical_core.chain_generation import ChainGenerationService

    class FakeGeneration(ChainGenerationService):
        def __init__(self):
            super().__init__(FakeCore())

        def safe_parse_datetime(self, _value):
            return None, None

        def compute_cp_child_due(self, _parent):
            return "20260102T090000Z", {"target_field": "due"}

        def build_child_from_parent(self, parent, child_due, child_field, next_link, parent_short, kind, cpmax, until_dt):
            return {
                "description": parent.get("description"),
                child_field: child_due,
                "link": next_link,
                "prevLink": parent_short,
                "chainID": parent.get("chainID"),
                "kind": kind,
                "chainMax": cpmax,
                "chainUntil": until_dt,
            }

    generation = FakeGeneration()
    plan = reconcile.build_reconcile_plan(parent, existing_children=[], hook=None, generation=generation)
    expect(plan.action == "spawn", f"expected spawn plan, got: {plan}")
    expect(plan.child and plan.child.get("link") == 3 and plan.child.get("prevLink") == "11111111", f"bad child plan: {plan}")
    evidence = reconcile.describe_plan(plan)
    expect(evidence.get("kind") == "cp", f"expected cp evidence, got: {evidence!r}")
    expect(evidence.get("next_link") == 3, f"expected next_link evidence, got: {evidence!r}")
    expect(evidence.get("child_field") == "due", f"expected child field evidence, got: {evidence!r}")

    capped = dict(parent, chainMax=2)
    plan = reconcile.build_reconcile_plan(capped, existing_children=[], hook=None, generation=generation)
    expect(plan.action == "legitimate_final" and "chainMax" in plan.reason, f"expected capped final, got: {plan}")

    class ExhaustingGeneration(FakeGeneration):
        def compute_cp_child_due(self, _parent):
            raise core.OccurrenceSearchExhausted(
                "cp scheduling", reference=date(9999, 1, 1), limit=1
            )

    terminal = reconcile.build_reconcile_plan(
        parent,
        existing_children=[],
        hook=None,
        generation=ExhaustingGeneration(),
    )
    expect(
        terminal.action == "legitimate_final" and "9999-12-31" in terminal.reason,
        f"date-limit exhaustion should be a terminal reconcile plan: {terminal}",
    )


def test_reconcile_plan_uses_task_business_calendar_context():
    """Reconcile scheduling and child construction must share the task calendar."""
    import nautical_core.reconcile as reconcile

    class FakeCore:
        active = False
        entered: list[str] = []

        @staticmethod
        def coerce_int(value, default=0):
            try:
                return int(value)
            except Exception:
                return default

        @classmethod
        def use_task_business_calendar(cls, task):
            if str(task.get("bc") or "") == "missing":
                raise ValueError("Unknown business calendar 'missing'")
            @contextlib.contextmanager
            def active_context():
                cls.entered.append(str(task.get("bc") or "default"))
                cls.active = True
                try:
                    yield
                finally:
                    cls.active = False
            return active_context()

    from nautical_core.chain_generation import ChainGenerationService

    class FakeGeneration(ChainGenerationService):
        def __init__(self):
            super().__init__(FakeCore)

        def safe_parse_datetime(self, _value):
            return None, None

        def compute_cp_child_due(self, _parent):
            expect(FakeCore.active, "reconcile computed a child outside the task calendar context")
            return "20260102T090000Z", {"target_field": "due"}

        def build_child_from_parent(self, parent, child_due, child_field, next_link, parent_short, kind, cpmax, until_dt):
            expect(FakeCore.active, "reconcile built a child outside the task calendar context")
            return {child_field: child_due, "link": next_link, "prevLink": parent_short, "chainID": parent.get("chainID")}

    parent = {
        "uuid": "11111111-0000-0000-0000-000000000001",
        "status": "completed",
        "chain": "on",
        "chainID": "11111111",
        "link": 1,
        "cp": "1d",
        "bc": "work",
    }
    generation = FakeGeneration()
    plan = reconcile.build_reconcile_plan(parent, existing_children=[], hook=None, generation=generation)
    expect(plan.action == "spawn", f"calendar-scoped reconcile did not spawn: {plan}")
    expect(FakeCore.entered == ["work"], f"unexpected calendar context entries: {FakeCore.entered!r}")
    expect(not FakeCore.active, "task business-calendar context leaked after planning")

    invalid = reconcile.build_reconcile_plan(dict(parent, bc="missing"), existing_children=[], hook=None, generation=generation)
    expect(invalid.action == "error", f"invalid calendar was not rejected: {invalid}")
    expect("invalid business calendar" in invalid.reason and "missing" in invalid.reason, invalid.reason)


def test_reconcile_expiration_candidate_requires_expiry_evidence():
    """Deleted chains should distinguish expiration, manual stop, and ambiguous evidence."""
    import nautical_core.reconcile as reconcile

    hook = _find_hook_file("on-modify.nautical")
    mod = _load_hook_module(hook, "_nautical_reconcile_expiration_candidate_test")
    parent = {
        "uuid": "11111111-0000-0000-0000-000000000001",
        "status": "deleted",
        "description": "expired occurrence",
        "cp": "7d",
        "chain": "on",
        "chainID": "11111111",
        "link": 2,
        "due": "20260720T060000Z",
        "until": "20260726T205959Z",
        "end": "20260726T205959Z",
    }
    is_candidate = lambda task: reconcile.is_orphan_expiration_candidate(
        task,
        safe_parse_datetime=mod._safe_parse_datetime,
    )

    expect(is_candidate(parent), "deletion exactly at until should be an expiration candidate")
    manual = dict(parent, end="20260726T205958Z")
    expect(not is_candidate(manual), "manual deletion before until must not advance")
    disposition, _reason = reconcile.deleted_chain_disposition(
        manual,
        safe_parse_datetime=mod._safe_parse_datetime,
    )
    expect(disposition == "manual", f"early deletion should stop the chain: {disposition!r}")
    no_until_disposition, _reason = reconcile.deleted_chain_disposition(
        {key: value for key, value in parent.items() if key != "until"},
        safe_parse_datetime=mod._safe_parse_datetime,
    )
    expect(no_until_disposition == "manual", f"deletion without until should stop the chain: {no_until_disposition!r}")
    malformed_disposition, _reason = reconcile.deleted_chain_disposition(
        dict(parent, until="not-a-date"),
        safe_parse_datetime=mod._safe_parse_datetime,
    )
    expect(malformed_disposition == "ambiguous", f"malformed evidence must fail closed: {malformed_disposition!r}")
    manual_plan = reconcile.build_reconcile_plan(manual, existing_children=[], hook=mod)
    expect(manual_plan.action == "manual_stop", f"manual deletion should disable the chain: {manual_plan}")
    expect(not is_candidate(dict(parent, status="completed")), "completed tasks use the completion candidate path")
    expect(not is_candidate(dict(parent, until="not-a-date")), "malformed until must fail closed")
    expect(not is_candidate(dict(parent, nextLink="22222222")), "already-linked expiration must not be reconsidered")


def test_reconcile_manual_deletion_stops_chain_without_child_lookup():
    """Hookless manual deletion should atomically persist chain:off without a child export."""
    path = Path(ROOT) / "nautical_core" / "tools" / "nautical_reconcile.py"
    tool = _load_hook_module(str(path), "_nautical_reconcile_manual_delete_test")
    hook_path = _find_hook_file("on-modify.nautical")
    hook = _load_hook_module(hook_path, "_nautical_reconcile_manual_delete_hook")
    parent = {
        "uuid": "11111111-0000-0000-0000-000000000001",
        "status": "deleted",
        "description": "manually deleted occurrence",
        "cp": "7d",
        "chain": "on",
        "chainID": "manual01",
        "link": 2,
        "due": "20260720T060000Z",
        "until": "20260726T205959Z",
        "end": "20260726T205958Z",
    }
    world = {"parent": dict(parent), "disabled": 0}

    @contextlib.contextmanager
    def parent_lock(_taskdata, parent_uuid):
        expect(parent_uuid == parent["uuid"], f"wrong parent lock identity: {parent_uuid}")
        yield True

    saved = {
        "export": tool._export,
        "lock": tool._parent_apply_lock,
        "fresh_parent": tool._fresh_parent,
        "existing": tool._existing_children,
        "disable": tool._disable_parent_chain,
    }
    try:
        def fake_export(_task_bin, filters, **_kwargs):
            if "status:deleted" in filters:
                return [dict(world["parent"])]
            return []

        tool._export = fake_export
        candidates = tool._candidate_rows("task", hook)
        expect([row.get("uuid") for row in candidates] == [parent["uuid"]], f"manual deletion was not discovered: {candidates}")

        tool._parent_apply_lock = parent_lock
        tool._fresh_parent = lambda _task_bin, _parent: dict(world["parent"])

        def unexpected_child_lookup(*_args, **_kwargs):
            raise AssertionError("manual deletion must not export a next-slot child")

        tool._existing_children = unexpected_child_lookup

        def disable_parent(_task_bin, _parent):
            world["disabled"] += 1
            world["parent"]["chain"] = "off"

        tool._disable_parent_chain = disable_parent
        plan, applied = tool._apply_parent_atomic(
            "task",
            hook,
            parent,
            taskdata=Path("/tmp/nautical-reconcile-manual-delete-test"),
        )
        expect(plan.action == "manual_stop" and applied == "off", f"manual deletion was not stopped: {plan}")
        expect(world["disabled"] == 1, f"manual deletion should be persisted once: {world}")

        world["parent"] = dict(parent, until="not-a-date")
        ambiguous, ambiguous_applied = tool._apply_parent_atomic(
            "task",
            hook,
            parent,
            taskdata=Path("/tmp/nautical-reconcile-manual-delete-test"),
        )
        expect(ambiguous.action == "error" and not ambiguous_applied, f"ambiguous deletion should fail closed: {ambiguous}")
        expect(world["disabled"] == 1, f"ambiguous deletion must not mutate the chain: {world}")
    finally:
        tool._export = saved["export"]
        tool._parent_apply_lock = saved["lock"]
        tool._fresh_parent = saved["fresh_parent"]
        tool._existing_children = saved["existing"]
        tool._disable_parent_chain = saved["disable"]


def test_reconcile_delayed_expiration_dry_run_converges_to_live_slot():
    """Dry-run should preview every elapsed expiration hop through the first live slot."""
    path = Path(ROOT) / "nautical_core" / "tools" / "nautical_reconcile.py"
    tool = _load_hook_module(str(path), "_nautical_reconcile_delayed_dry_run_test")
    hook_path = _find_hook_file("on-modify.nautical")
    hook = _load_hook_module(hook_path, "_nautical_reconcile_delayed_dry_run_hook")
    recovery_at = hook.core.build_local_datetime(date(2026, 7, 23), (9, 30))
    parent = {
        "uuid": "11111111-0000-0000-0000-000000000001",
        "status": "deleted",
        "description": "delayed daily occurrence",
        "cp": "1d",
        "chain": "on",
        "chainID": "delayed1",
        "link": 1,
        "due": hook.core.fmt_isoz(hook.core.build_local_datetime(date(2026, 7, 20), (9, 0))),
        "until": hook.core.fmt_isoz(hook.core.build_local_datetime(date(2026, 7, 20), (10, 0))),
        "end": hook.core.fmt_isoz(hook.core.build_local_datetime(date(2026, 7, 20), (10, 0))),
    }
    original = tool._existing_children_for_plan
    try:
        tool._existing_children_for_plan = lambda _task_bin, _parent, _hook: []
        outcomes = tool._reconcile_candidate(
            "task",
            hook,
            parent,
            taskdata=None,
            apply=False,
            max_expiration_hops=8,
            recovery_at=recovery_at,
        )
        limited = tool._reconcile_candidate(
            "task",
            hook,
            parent,
            taskdata=None,
            apply=False,
            max_expiration_hops=2,
            recovery_at=recovery_at,
        )
        capped = tool._reconcile_candidate(
            "task",
            hook,
            dict(parent, chainMax=2),
            taskdata=None,
            apply=False,
            max_expiration_hops=8,
            recovery_at=recovery_at,
        )
        anchor_parent = {
            **parent,
            "anchor": "w:mon..sun@t=09:00,13:00",
            "anchor_mode": "skip",
            "chainID": "delayed-anchor",
            "until": hook.core.fmt_isoz(hook.core.build_local_datetime(date(2026, 7, 20), (14, 0))),
            "end": hook.core.fmt_isoz(hook.core.build_local_datetime(date(2026, 7, 20), (14, 0))),
        }
        anchor_parent.pop("cp")
        anchor_outcomes = tool._reconcile_candidate(
            "task",
            hook,
            anchor_parent,
            taskdata=None,
            apply=False,
            max_expiration_hops=8,
            recovery_at=hook.core.build_local_datetime(date(2026, 7, 21), (14, 30)),
        )
    finally:
        tool._existing_children_for_plan = original

    plans = [plan for plan, _applied in outcomes]
    expect([plan.action for plan in plans] == ["spawn", "spawn", "spawn"], f"unexpected recovery path: {plans}")
    expect([plan.parent.get("link") for plan in plans] == [1, 2, 3], f"recovery skipped chain links: {plans}")
    final_until, final_until_err = hook._safe_parse_datetime((plans[-1].child or {}).get("until"))
    expect(not final_until_err and final_until is not None and final_until > recovery_at, f"final slot is already expired: {plans[-1]}")
    expect(
        [plan.action for plan, _applied in limited] == ["spawn", "spawn", "partial"],
        f"hop limit should leave an actionable resumable partial result: {limited}",
    )
    expect("hop limit" in limited[-1][0].reason, f"missing hop-limit guidance: {limited[-1][0]}")
    expect(
        [plan.action for plan, _applied in capped] == ["spawn", "legitimate_final"],
        f"chainMax was not enforced during delayed recovery: {capped}",
    )
    expect(
        [plan.next_link for plan, _applied in anchor_outcomes] == [2, 3, 4, 5],
        f"multi-time anchor recovery skipped slots: {anchor_outcomes}",
    )


def test_reconcile_delayed_expiration_apply_follows_exact_children():
    """Apply should follow exact adjacent children and stop after reaching a live occurrence."""
    path = Path(ROOT) / "nautical_core" / "tools" / "nautical_reconcile.py"
    tool = _load_hook_module(str(path), "_nautical_reconcile_delayed_apply_test")
    root = {
        "uuid": "11111111-0000-0000-0000-000000000001",
        "status": "deleted",
        "cp": "1d",
        "chain": "on",
        "chainID": "delayed1",
        "link": 1,
        "due": "20260720T090000Z",
        "until": "20260720T100000Z",
        "end": "20260720T100000Z",
    }
    tasks = {
        1: root,
        2: {
            **root,
            "uuid": "22222222-0000-0000-0000-000000000002",
            "link": 2,
            "due": "20260721T090000Z",
            "until": "20260721T100000Z",
        },
        3: {
            **root,
            "uuid": "33333333-0000-0000-0000-000000000003",
            "link": 3,
            "due": "20260722T090000Z",
            "until": "20260722T100000Z",
        },
        4: {
            **root,
            "uuid": "44444444-0000-0000-0000-000000000004",
            "status": "pending",
            "link": 4,
            "due": "20260723T090000Z",
            "until": "20260723T100000Z",
        },
    }
    calls = []
    original = (tool._apply_parent_atomic, tool._next_recovery_child)
    try:
        class FakeHook:
            @staticmethod
            def _safe_parse_datetime(value):
                try:
                    return datetime.strptime(str(value), "%Y%m%dT%H%M%SZ").replace(tzinfo=timezone.utc), None
                except Exception:
                    return None, "invalid datetime"

        hook = FakeHook()

        def apply_parent(_task_bin, _hook, parent, *, taskdata, lease_held=False, verified_children=None):
            link = int(parent["link"])
            calls.append(("apply", link, taskdata))
            child = tasks[link + 1]
            plan = tool.reconcile.ReconcilePlan(
                "spawn",
                parent,
                link + 1,
                "expired link missing next link",
                child=child,
                child_due=child.get("due"),
            )
            return plan, str(child["uuid"])[:8]

        def next_child(_task_bin, parent, child_short):
            link = int(parent["link"])
            calls.append(("lookup", link, child_short))
            return tasks[link + 1]

        tool._apply_parent_atomic = apply_parent
        tool._next_recovery_child = next_child
        outcomes = tool._reconcile_candidate(
            "task",
            hook,
            root,
            taskdata=Path("/tmp/nautical-reconcile-delayed-test"),
            apply=True,
            max_expiration_hops=8,
            recovery_at=datetime(2026, 7, 23, 9, 30, tzinfo=timezone.utc),
        )
        limited = tool._reconcile_candidate(
            "task",
            hook,
            root,
            taskdata=Path("/tmp/nautical-reconcile-delayed-test"),
            apply=True,
            max_expiration_hops=2,
            recovery_at=datetime(2026, 7, 23, 9, 30, tzinfo=timezone.utc),
        )

        def fail_second_apply(_task_bin, _hook, parent, *, taskdata, lease_held=False, verified_children=None):
            if int(parent["link"]) == 2:
                raise TimeoutError("parent lock timed out")
            return apply_parent(
                _task_bin,
                _hook,
                parent,
                taskdata=taskdata,
                lease_held=lease_held,
                verified_children=verified_children,
            )

        tool._apply_parent_atomic = fail_second_apply
        interrupted = tool._reconcile_candidate(
            "task",
            hook,
            root,
            taskdata=Path("/tmp/nautical-reconcile-delayed-test"),
            apply=True,
            max_expiration_hops=8,
            recovery_at=datetime(2026, 7, 23, 9, 30, tzinfo=timezone.utc),
        )

        tool._apply_parent_atomic = apply_parent
        tool._next_recovery_child = lambda *_args, **_kwargs: (_ for _ in ()).throw(
            TimeoutError("child lookup timed out")
        )
        lookup_interrupted = tool._reconcile_candidate(
            "task",
            hook,
            root,
            taskdata=Path("/tmp/nautical-reconcile-delayed-test"),
            apply=True,
            max_expiration_hops=8,
            recovery_at=datetime(2026, 7, 23, 9, 30, tzinfo=timezone.utc),
        )

        tool._next_recovery_child = next_child
        tasks[4]["until"] = "not-a-date"
        invalid_terminal = tool._reconcile_candidate(
            "task",
            hook,
            root,
            taskdata=Path("/tmp/nautical-reconcile-delayed-test"),
            apply=True,
            max_expiration_hops=8,
            recovery_at=datetime(2026, 7, 23, 9, 30, tzinfo=timezone.utc),
        )
    finally:
        tool._apply_parent_atomic, tool._next_recovery_child = original

    expect([plan.parent.get("link") for plan, _applied in outcomes] == [1, 2, 3], f"apply did not converge: {outcomes}")
    expect([applied for _plan, applied in outcomes] == ["22222222", "33333333", "44444444"], f"wrong child traversal: {outcomes}")
    expect(
        [plan.action for plan, _applied in limited] == ["spawn", "spawn", "partial"],
        f"apply hop limit was not enforced: {limited}",
    )
    expect(
        [plan.action for plan, _applied in interrupted] == ["spawn", "error"],
        f"successful hops were lost after an apply failure: {interrupted}",
    )
    expect(
        [plan.action for plan, _applied in lookup_interrupted] == ["spawn", "error"],
        f"successful hops were lost after a lookup failure: {lookup_interrupted}",
    )
    expect(
        [plan.action for plan, _applied in invalid_terminal] == ["spawn", "spawn", "spawn", "error"],
        f"invalid live terminal occurrence was accepted: {invalid_terminal}",
    )
    expect("native until" in invalid_terminal[-1][0].reason, f"terminal error was unclear: {invalid_terminal[-1][0]}")
    expect(
        ("lookup", 1, "22222222") in calls and ("lookup", 2, "33333333") in calls,
        f"recovery did not use narrow child lookups: {calls}",
    )


